import numpy as np
import pandas as pd

ANION_SWEEP = [0.08, 0.04, 0.02, 0.01]
_bl_dist_factors = [1.20, 1.30, 1.40]
_bl_bv_cutoffs = [0.01, 0.02, 0.04, 0.08]


def _resolve_eir_inputs(quality_csv=None, cif_directory=None):
    """Find the CIF directory and the newest quality CSV from what is to hand."""
    import glob as _glob

    if not cif_directory:
        cif_directory = globals().get('_cif_dir')
    if not cif_directory and 'resolve_cif_directory' in globals():
        cif_directory = resolve_cif_directory(globals().get('dfq'), None, ask=False)
    if not cif_directory or not os.path.isdir(cif_directory):
        print('Could not locate the CIF directory. Pass cif_directory and re-run.')
        return None, None

    if not quality_csv:
        _hits = sorted(_glob.glob(os.path.join(cif_directory, 'outputs',
                                               '*_quality.csv')),
                       key=os.path.getmtime, reverse=True)
        quality_csv = _hits[0] if _hits else None
    if not quality_csv or not os.path.exists(quality_csv):
        print('No *_quality.csv found. Pass quality_csv and re-run.')
        return None, None

    print(f'  CIF directory: {cif_directory}')
    print(f'  quality CSV  : {os.path.basename(quality_csv)}')
    return quality_csv, cif_directory


def _clean_sites(df):
    """Dominant species in structures that pass every geometry screen."""
    df = df[df['is_dominant_species'].astype(str).eq('True')]
    keep = ~(df['structure_core_geometry_plausible'].astype(str).eq('False')
             | df['structure_bvs_geometry_plausible'].astype(str).eq('False')
             | df['anion_packing_plausible'].astype(str).eq('False')
             | df['structure_cn_plausible'].astype(str).eq('False'))
    return df[keep]


# ---------------------------------------------------------------------------
# 1. MEASURED AGAINST ADDITIVE EXPECTED DISTANCES
# ---------------------------------------------------------------------------
def compare_expected_distances(quality_csv=None, cif_directory=None):
    """
    Recompute the radii-screen ratio against MEASURED bond lengths and report
    the coordination dependence that RADII_CN_SLOPE exists to correct.

    If the expected distances are right at every coordination, that dependence
    should largely vanish and a refitted slope should measure near zero. The
    ratio_min column is the one to watch: it compares the shortest contact in
    this structure against the shortest ever observed for this ion
    configuration, which is like against like and needs no fitted threshold.
    """
    quality_csv, _ = _resolve_eir_inputs(quality_csv, cif_directory)
    if quality_csv is None:
        return None

    d = pd.read_csv(quality_csv)
    d = d[d['is_dominant_species'].astype(str).eq('True')]
    d = d.dropna(subset=['min_bond_length', 'cn', 'valence'])

    rows = []
    for _, r in d.iterrows():
        lig = (r.get('fields_describe_ligand')
               or str(r.get('ligand_types') or 'O').split(',')[0] or 'O')
        e = expected_bond_length(r['element'], r['valence'], r['cn'], lig)
        if not e:
            continue
        rows.append({'icsd': r.get('icsd_code'), 'element': r['element'],
                     'cn': int(r['cn']), 'gii': r.get('gii'),
                     'observed': r['min_bond_length'],
                     'ratio_mean': r['min_bond_length'] / e['mean'],
                     'ratio_min': (r['min_bond_length'] / e['min']
                                   if e['min'] else np.nan),
                     'ratio_shannon': r.get('core_shortest_contact_ratio'),
                     'tier': e['tier'], 'source': e['source']})
    out = pd.DataFrame(rows)
    if not len(out):
        print('  nothing resolved')
        return None
    print(f'  {len(out)} sites resolved of {len(d)}')
    print()
    print('  TIER COVERAGE')
    _lab = {1: 'measured', 2: 'interpolated', 3: 'extrapolated',
            4: 'Shannon additive'}
    for t, g in out.groupby('tier'):
        print(f'    {t}  {_lab[t]:18} {len(g):5}  ({100 * len(g) / len(out):.1f}%)')

    sound = out[pd.to_numeric(out['gii'], errors='coerce') < 0.25]
    print()
    print('  CONTACT RATIO BY COORDINATION, structures with GII < 0.25')
    print(f"  {'CN':>4} {'n':>6} {'vs Shannon':>12} {'vs measured mean':>18} "
          f"{'vs measured min':>17}")
    for cn, g in sound.groupby('cn'):
        if len(g) < 20:
            continue
        print(f'  {cn:4d} {len(g):6d} {g["ratio_shannon"].median():12.3f} '
              f'{g["ratio_mean"].median():18.3f} {g["ratio_min"].median():17.3f}')
    print()
    print('  The Shannon column falls with CN; that gradient is what')
    print('  RADII_CN_SLOPE corrects. If the measured columns are flat, the')
    print('  slope was compensating for a wrong expected distance and can go.')
    return out


# ---------------------------------------------------------------------------
# 2. WHICH CUT-OFF SHOULD DEFINE THE COORDINATION SHELL
# ---------------------------------------------------------------------------
def _shell_by_valence_adaptive(ds, R0, b, valence, cn_seed, element, anion):
    """Measured shell boundary, seeded from the gap shell. See bv_shell_boundary."""
    cn, _ = bv_shell_cn_adaptive(ds, R0, b, valence, cn_seed,
                                 element=element, anion=anion)
    return sorted(ds)[:cn] if cn else []


def _shell_by_valence(ds, R0, b, s_min):
    out = []
    for d in sorted(ds):
        if np.exp((R0 - d) / b) < s_min:
            break
        out.append(d)
    return out


def _bvs_of(ds, R0, b):
    return float(sum(np.exp((R0 - d) / b) for d in ds))


def compare_shell_rules(quality_csv=None, cif_directory=None):
    """
    Rebuild the bond valence sum under several shell rules and report the
    deviation by site type. The B site is the control: an octahedron has one
    shell however you cut it, so any rule that moves it is wrong whatever it
    does to the larger cation. Read the CN columns before the deviations.

    NOTE: the A/B labelling below is PEROVSKITE-SPECIFIC. It splits the
    cations of each structure by radius, which names the two sites of an
    ABO3 correctly and means nothing in a rock salt or a spinel with three
    cations. This is a measurement tool for that family, not a general one.
    """
    quality_csv, cif_directory = _resolve_eir_inputs(quality_csv, cif_directory)
    if quality_csv is None:
        return None

    df = pd.read_csv(quality_csv)
    _before = df['filename'].nunique()
    df = _clean_sites(df)
    df = df[df['contact_above_floor'].astype(str).ne('False')]
    print(f'  {_before - df["filename"].nunique()} structures excluded: '
          f'at least one geometry screen failed')
    print(f'  {len(df)} dominant cation sites in {df["filename"].nunique()} structures')

    rad = pd.to_numeric(df['cation_radius'], errors='coerce')
    df = df.assign(_rad=rad)
    df['_site_type'] = np.where(
        df['_rad'] >= df.groupby('filename')['_rad'].transform('max') - 1e-9,
        'A', 'B')

    cache, rows = {}, []
    for _, r in df.iterrows():
        fn = r['filename']
        path = os.path.join(cif_directory, fn)
        if path not in cache:
            try:
                cache[path] = neighbour_distances(path)
            except Exception as e:
                print(f'  ! {fn}: {type(e).__name__}: {e}')
                cache[path] = {}
        per_anion = _distances_for_row(cache[path], r.get('coords'), r.get('element'))
        if not per_anion:
            continue
        el, v = r.get('element'), r.get('valence')
        params = {}
        for ael in per_anion:
            p = get_bv_parameters_fractional(el, v, ael)
            if p and p[0] is not None:
                params[ael] = p
        if not params:
            continue

        rec = {'filename': fn, 'icsd_code': r.get('icsd_code'),
               'element': el, 'valence': v, 'site_type': r['_site_type']}

        def total(rule, *args):
            s, n = 0.0, 0
            for ael, dl in per_anion.items():
                if ael not in params:
                    continue
                R0, b = params[ael]
                if rule is _shell_by_valence:
                    sh = _shell_by_valence(dl, R0, b, *args)
                elif rule is _shell_by_valence_adaptive:
                    sh = _shell_by_valence_adaptive(dl, R0, b, args[0], args[1],
                                                    el, ael)
                else:
                    sh = rule(dl, *args)
                s += _bvs_of(sh, R0, b)
                n += len(sh)
            return s, n

        rec['bvs_gap'], rec['cn_gap'] = total(_shell_by_gap, r.get('cn_gap_shell'))
        rec['bvs_adapt'], rec['cn_adapt'] = total(
            _shell_by_valence_adaptive, v, r.get('cn_gap_shell'))
        for f in _bl_dist_factors:
            rec[f'bvs_d{f}'], rec[f'cn_d{f}'] = total(_shell_by_distance, f)
        for s_min in _bl_bv_cutoffs:
            rec[f'bvs_s{s_min}'], rec[f'cn_s{s_min}'] = total(_shell_by_valence, s_min)
        rows.append(rec)

    out = pd.DataFrame(rows)
    if not len(out):
        print('  nothing measured')
        return None

    rules = ['gap'] + [f'd{f}' for f in _bl_dist_factors] + \
            [f's{s}' for s in _bl_bv_cutoffs] + ['adapt']
    formal = out['valence'].abs()
    print()
    print('  deviation from formal valence (%), by site type')
    print(f"  {'rule':10} {'A mean':>9} {'A med':>9} {'A CN':>7} "
          f"{'B mean':>9} {'B med':>9} {'B CN':>7}")
    for k in rules:
        dev = (out[f'bvs_{k}'] - formal) / formal * 100
        line = f'  {k:10}'
        for t in ('A', 'B'):
            m = out['site_type'].eq(t)
            line += (f'{dev[m].mean():9.2f}{dev[m].median():9.2f}'
                     f'{out.loc[m, f"cn_{k}"].mean():7.1f}')
        print(line)
    print()
    print('  structure GII (cation sites only), and the 0.20 pass rate')
    print(f"  {'rule':10} {'median':>9} {'mean':>9} {'<=0.20':>9}")
    for k in rules:
        dd = out[f'bvs_{k}'] - formal
        g = (dd.pow(2).groupby(out['filename']).mean()) ** 0.5
        print(f'  {k:10}{g.median():9.4f}{g.mean():9.4f}'
              f'{100 * (g <= 0.20).mean():8.1f}%')
    print()
    print('  A rule that fixes the larger cation by summing twenty bonds has')
    print('  not fixed anything; the B-site column is the control.')
    return out


# ---------------------------------------------------------------------------
# 3. DOES THE CUT-OFF HAVE TO DIFFER AT THE TWO ENDS OF A BOND
# ---------------------------------------------------------------------------
def sweep_anion_cutoff(quality_csv=None, cif_directory=None, limit=None):
    """
    Rebind ANION_BV_CUTOFF across a sweep and restore it in a finally block.

    s is a property of the bond, so a contact admitted to the cation sum must be
    admitted to the anion sum. The control here is COORDINATION: an oxygen in a
    Pbnm perovskite is 2 B + 4 A. A cut-off that inflates that is admitting a
    second shell whatever it does to the deviations.
    """
    global ANION_BV_CUTOFF

    quality_csv, cif_directory = _resolve_eir_inputs(quality_csv, cif_directory)
    if quality_csv is None:
        return None

    df = _clean_sites(pd.read_csv(quality_csv))
    valences = {fn: dict(zip(g['element'], g['valence']))
                for fn, g in df.groupby('filename')}
    files = sorted(valences)
    if limit:
        files = files[:limit]
    print(f'  {len(files)} structures, {len(ANION_SWEEP)} cut-offs, '
          f'{len(files) * len(ANION_SWEEP)} analyses')

    original, rows, failed = ANION_BV_CUTOFF, [], 0
    try:
        for cut in ANION_SWEEP:
            ANION_BV_CUTOFF = cut
            print(f'    cut-off {cut} ...', end='', flush=True)
            for fn in files:
                try:
                    sites = calculate_anion_bvs(os.path.join(cif_directory, fn),
                                                valences[fn])
                except Exception:
                    failed += 1
                    continue
                for s in sites:
                    rows.append({'cut': cut, 'filename': fn,
                                 'label': s.get('anion_label'),
                                 'cn': s.get('anion_cn'),
                                 'bvs': s.get('anion_bvs'),
                                 'dev': s.get('anion_deviation'),
                                 'ligands': s.get('anion_ligands')})
            print(' done')
    finally:
        ANION_BV_CUTOFF = original
        print(f'  ANION_BV_CUTOFF restored to {ANION_BV_CUTOFF}')
    if failed:
        print(f'  {failed} analyses could not be run')

    out = pd.DataFrame(rows)
    if not len(out):
        print('  nothing measured')
        return None
    tol = globals().get('ANION_CONSISTENT_TOL', 0.20)

    print()
    print('  THE CONTROL: coordination number')
    print(f"  {'cut-off':>8} {'mean CN':>9} {'median CN':>10} {'CN modes':>24}")
    for cut, g in out.groupby('cut'):
        modes = g['cn'].value_counts(normalize=True).head(3)
        txt = ', '.join(f'{int(k)}:{100 * v:.0f}%' for k, v in modes.items())
        print(f'  {cut:8.2f}{g["cn"].mean():9.2f}{g["cn"].median():10.1f}{txt:>25}')
    print()
    print('  THEN the sums')
    print(f"  {'cut-off':>8} {'BVS mean':>10} {'BVS med':>10} {'|dev|>tol':>11}")
    for cut, g in out.groupby('cut'):
        print(f'  {cut:8.2f}{g["bvs"].mean():10.4f}{g["bvs"].median():10.4f}'
              f'{100 * (g["dev"].abs() > tol).mean():10.1f}%')
    return out


print('Measurement tools loaded: compare_expected_distances(), '
      'compare_shell_rules(), sweep_anion_cutoff()')
print('None of them changes a result.')
